import styles from "./Article.module.css";

export default function Article({ selectedSub }) {
    if (!selectedSub) return null;

    return (
        <div
            className={styles.article}
            style={{ left: "15vw", top: "20vh" }}
            onClick={() => {
                window.open(selectedSub.sub.article.article_url, "_blank");
            }}
        >
            {/* <p className={styles.parent}>{node.data.name}</p>
            <p className={styles.name}>{sub.name}</p> */}
            <p className={styles.title}>{selectedSub.sub.article.title}</p>
            <div className={styles.row}>
                <span>{selectedSub.sub.article.summary}</span>
            </div>
            <br />
            <div className={styles.more}>Read more</div>
        </div>
    );
}
